CREATE TABLE report_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, report_version_id uuid NOT NULL REFERENCES report_versions(id) ON DELETE CASCADE, token_hash char(64) NOT NULL UNIQUE, pin_hash char(64) NOT NULL, failed_attempts integer NOT NULL DEFAULT 0, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(report_version_id));
ALTER TABLE report_access ENABLE ROW LEVEL SECURITY; ALTER TABLE report_access FORCE ROW LEVEL SECURITY;
CREATE POLICY report_access_isolation ON report_access USING (school_id = NULLIF(current_setting('app.school_id',true),'')::uuid) WITH CHECK (school_id = NULLIF(current_setting('app.school_id',true),'')::uuid);
GRANT SELECT, INSERT, UPDATE ON report_access TO ramu_app;
CREATE FUNCTION verify_parent_report(p_token text,p_pin text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a report_access%ROWTYPE; v jsonb; BEGIN SELECT * INTO a FROM report_access WHERE token_hash=encode(digest(p_token,'sha256'),'hex') FOR UPDATE; IF NOT FOUND OR a.failed_attempts >= 5 THEN RETURN NULL; END IF; IF a.pin_hash<>encode(digest(p_pin,'sha256'),'hex') THEN UPDATE report_access SET failed_attempts=failed_attempts+1 WHERE id=a.id; RETURN NULL; END IF; SELECT snapshot INTO v FROM report_versions WHERE id=a.report_version_id; RETURN v; END; $$;
GRANT EXECUTE ON FUNCTION verify_parent_report(text,text) TO ramu_app;
